head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > E > onviewchange]<br/>키보드 또는 터치 스크롤 조작을 통해 DatePicker 컴포넌트의 선택 날짜가 변경되면 발생합니다.",
    "validation" : [
        "터치 스크롤 조작을 통해 DatePicker 컴포넌트의 선택 날짜가 변경되면 onviewchange 이벤트가 발생합니다.",
        "스크립트(setValue())를 통해 값이 변경된 경우에는 onviewchange 이벤트가 발생하지 않습니다.",
        "info 파라미터로 변경 정보가 객체로 전달됩니다.",
        "info.oldValue 에 변경되기 전 날짜값을 갖습니다.",
        "info.newValue 에 변경된 후 날짜값을 갖습니다.",
        "info.oldSelectedIndex 에 변경되기 전 선택값의 인덱스를 갖습니다.",
        "info.newSelectedIndex 에 변경된 후 선택값의 인덱스를 갖습니다.",
        "사용자 조작에 의한 값 변경 시 'onviewchange -> onchange' 순서로 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 라벨: 수동 테스트 안내 (터치/마우스 스크롤 조작 → onviewchange -> onchange 순서 검증)
    $c.gcm.createLabel('label="[수동 테스트 안내] DatePicker 의 스핀(휠) 영역을 마우스 드래그 또는 터치 스크롤로 조작하여 날짜를 변경하면 onviewchange -> onchange 순서로 이벤트가 발생합니다."', '', 'label1');

    let calendarValueType = con_calendarValueType.getText();

    let properties = {
        calendarValueType : calendarValueType
    };

    let cList = $c.gcm.createCList(properties);

    // onviewchange / onchange 핸들러 모두 등록 - 공통 모듈 사용
    let eList = $c.gcm.createEList(["onviewchange", "onchange"]);

    await $c.gcm.createBasicDatePicker(cList, eList);
};



// 스크립트(setValue) 호출 → onviewchange 미발생 / onchange 만 발생 확인
scwin.btn_setValue_onclick = function (e) {
    let inputValue = par_value.getText();
    wf_body_bottom.getObj("scwin").setReturnValue("[setValue 호출] '" + inputValue + "'");
    target1.setValue(inputValue);
};



// 사용자의 키보드/터치 스크롤 조작으로 선택 날짜가 변경되면 발생
scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldSelectedIndex : " + info.oldSelectedIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newSelectedIndex : " + info.newSelectedIndex);
};



// 발생 순서 확인용 (onviewchange -> onchange)
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생]");
};
